using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckLimbo {
public enum LimboAttempt {Waiting,Approach,Clear,Failed,Eliminated}
public sealed class LimboRacer:MonoBehaviour {
 public LimboMatch match;public SportsEventTruck truck;public LimboBar bar;public int slot;public float laneCenter;public Vector3 start;public float standingTravel=.75f,compressedTravel=.12f;
 public LimboAttempt Phase{get;private set;}public float Compression{get;private set;}public float Roll{get;private set;}public bool HitBar{get;private set;}public string Reaction{get;private set;}="READY";public bool Entered{get;private set;}public float ClosestClearance{get;private set;}public float AttemptTime{get;private set;}public int SolidBarContacts{get;private set;}
 RigidbodyConstraints raceConstraints;Collider[] hull;Bounds previous;float fatigue,groundAge;Vector3 restCOM;float originalDamping;Quaternion barStartRotation;Vector3 barStart;
 void Awake(){hull=GetComponentsInChildren<Collider>(true);restCOM=truck.body.centerOfMass;originalDamping=truck.body.angularDamping;raceConstraints=truck.body.constraints;}
 Bounds Hull(){bool found=false;Bounds result=default;foreach(var c in hull)if(c!=null&&c.enabled&&!c.isTrigger&&c.attachedRigidbody==truck.body){if(!found){result=c.bounds;found=true;}else result.Encapsulate(c.bounds);}return result;}
 public void Prepare(bool active,float height){Compression=fatigue=groundAge=AttemptTime=0;HitBar=Entered=false;ClosestClearance=float.PositiveInfinity;SolidBarContacts=0;LastContact="none";Reaction=active?"BREATHE. LINE UP.":"WATCHING THE PARTY";foreach(var w in truck.wheels)w.spring.maxLength=standingTravel;truck.body.centerOfMass=restCOM;truck.body.angularDamping=2.3f;truck.Prepare(start,Quaternion.identity,active);truck.body.constraints=raceConstraints|RigidbodyConstraints.FreezePositionX|RigidbodyConstraints.FreezePositionZ|RigidbodyConstraints.FreezeRotationY;Phase=active?LimboAttempt.Waiting:LimboAttempt.Eliminated;bar.Prepare(height);previous=Hull();}
 public void Hold(){if(Phase!=LimboAttempt.Waiting)return;truck.TickDrive(Vector2.zero);foreach(var w in truck.wheels){w.MotorTorque=0;w.BrakeTorque=truck.brakeTorque;}}
 public void Release(){if(Phase!=LimboAttempt.Waiting)return;truck.body.constraints=raceConstraints;var v=truck.body.linearVelocity;truck.body.linearVelocity=new Vector3(0,v.y,0);truck.body.angularVelocity=Vector3.zero;Phase=LimboAttempt.Approach;AttemptTime=0;previous=Hull();barStart=bar.body.position;barStartRotation=bar.body.rotation;Debug.Log("LIMBO_GO slot="+slot+" round="+match.rules.Round+" p="+truck.body.position+" v="+truck.body.linearVelocity+" rotation="+truck.body.rotation.eulerAngles);}
 public string LastContact{get;private set;}="none";
 public void ContactBar(Collision collision){if(Phase!=LimboAttempt.Approach)return;HitBar=true;SolidBarContacts++;var c=collision.GetContact(0);LastContact="object="+collision.collider.name+" point="+c.point+" normal="+c.normal+" normalSpeed="+Mathf.Abs(Vector3.Dot(collision.relativeVelocity,c.normal)).ToString("F3");Reaction="OH-NO WOBBLE";}
 public void Step(Vector2 command,bool crouch,float dt){if(Phase==LimboAttempt.Waiting){Hold();return;}if(Phase!=LimboAttempt.Approach){truck.TickDrive(Vector2.zero);return;}AttemptTime+=dt;var body=truck.body;bool grounded=false;foreach(var w in truck.wheels)grounded|=w.IsGrounded;groundAge=grounded?.15f:Mathf.Max(0,groundAge-dt);
  fatigue=crouch?fatigue+dt:Mathf.Max(0,fatigue-dt*2);float reserve=1-Mathf.Clamp01((fatigue-2.5f)/3)*.7f;Compression=Mathf.MoveTowards(Compression,crouch?reserve:0,dt*(crouch?2.8f:1.4f));foreach(var w in truck.wheels)w.spring.maxLength=Mathf.Lerp(standingTravel,compressedTravel,Compression);
  truck.TickDrive(new Vector2(command.x*.18f,command.y));Roll=Vector3.SignedAngle(Vector3.up,transform.up,Vector3.forward);float desired=-command.x*(Compression>.5f?58:22);float correction=Mathf.Clamp((Mathf.DeltaAngle(Roll,desired))*.14f-body.angularVelocity.z*2,-5,5);if(groundAge>0)body.AddTorque(Vector3.forward*correction,ForceMode.Acceleration);body.centerOfMass=Vector3.Lerp(restCOM,restCOM+new Vector3(command.x*.2f,-.12f,0),Compression);Reaction=Mathf.Abs(Roll)>35?"SIDEWAYS LIMBO":Compression>.8f?"BELLY SLIDE":Compression>.25f?"TRUCK SQUAT":Mathf.Abs(command.x)>.3f?"SHY LEAN":"EASY DOES IT";
  var bounds=Hull();float plane=bar.Plane;bool entry=LimboRules.ValidEntry(previous.max.z,bounds.max.z,plane,bounds.min.x,bounds.max.x,laneCenter-3.6f,laneCenter+3.6f,groundAge>0);if(entry)Entered=true;float movement=Vector3.Distance(barStart,bar.body.position);if(Quaternion.Angle(barStartRotation,bar.body.rotation)>3)movement=Mathf.Max(movement,.1f);if(bounds.max.z>plane-.3f&&bounds.min.z<plane+.3f)ClosestClearance=Mathf.Min(ClosestClearance,match.rules.Height-bounds.max.y);
  if(HitBar||movement>.06f){Finish(false,"OH-NO! THE BAR MOVED");return;}
  if(LimboRules.FullClearance(bounds.min.z,plane,Entered,HitBar,movement)){Finish(true,"HAPPY WIGGLE");return;}
  if(Mathf.Abs(body.position.x-laneCenter)>5.5f||body.position.y<-.8f||body.position.z>plane+8&&!Entered||AttemptTime>35){Finish(false,AttemptTime>35?"TIME UP — TRY NEXT ROUND":"MISSED THE OPENING");return;}previous=bounds;
 }
 void Finish(bool success,string reaction){Debug.Log("LIMBO_RESOLVE slot="+slot+" round="+match.rules.Round+" height="+match.rules.Height+" success="+success+" reason="+reaction+" p="+truck.body.position+" bounds="+Hull()+" bar="+bar.body.position+" start="+barStart+" barAngle="+Quaternion.Angle(barStartRotation,bar.body.rotation)+" contact="+LastContact);Phase=success?LimboAttempt.Clear:LimboAttempt.Failed;Reaction=reaction;truck.TickDrive(Vector2.zero);foreach(var w in truck.wheels)w.MotorTorque=0;bool style=success&&Mathf.Abs(Roll)>12&&Mathf.Abs(Roll)<65&&truck.body.linearVelocity.magnitude<4.5f;match.Record(slot,success,ClosestClearance>=0&&ClosestClearance<.12f,style);}
 public void Restore(){truck.body.constraints=raceConstraints;foreach(var w in truck.wheels)w.spring.maxLength=standingTravel;truck.body.centerOfMass=restCOM;truck.body.angularDamping=originalDamping;truck.Power(false);truck.StopSound();if(!truck.body.isKinematic)truck.body.linearVelocity=truck.body.angularVelocity=Vector3.zero;truck.body.isKinematic=true;}
 void OnDisable(){if(truck!=null&&truck.body!=null)Restore();}
}
}
